export function AreaAtuacao() {
  const ref = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;

    const paths = svg.querySelectorAll<SVGPathElement>(".cidade-path");
    for (const path of paths) {
      const length = path.getTotalLength();
      path.style.strokeDasharray = `${length}`;
      path.style.strokeDashoffset = `${length}`;
    }

    const ctx = gsap.context(() => {
      const tl = gsap.timeline({
        scrollTrigger: { trigger: ref.current, start: "top 70%", once: true },
      });
      tl.to(paths, {
        strokeDashoffset: 0,
        duration: 1.2,
        stagger: 0.35,
        ease: "power2.out",
      })
        .from(
          ".cidade-pin",
          {
            scale: 0,
            opacity: 0,
            transformOrigin: "center",
            stagger: 0.2,
            duration: 0.5,
            ease: "back.out(3)",
          },
          "-=0.8"
        )
        .from(
          ".cidade-label",
          { opacity: 0, y: 8, stagger: 0.2, duration: 0.5 },
          "-=0.6"
        )
        .from(
          ".cidade-item",
          { opacity: 0, x: -12, stagger: 0.1, duration: 0.5 },
          "-=1"
        );
    }, ref);

    return () => ctx.revert();
  }, []);

  return (
    <section className="mx-auto max-w-6xl px-4 py-24 md:px-6" ref={ref}>
      <h2 className="mb-4 text-center font-bold text-3xl tracking-tight md:text-4xl">
        Onde eu atuo
      </h2>
      <p className="mx-auto mb-16 max-w-xl text-center text-muted-foreground">
        Cobertura na região metropolitana de Fortaleza, com foco em três
        cidades.
      </p>

      <div className="grid items-center gap-10 md:grid-cols-[1.2fr_1fr]">
        <svg
          aria-label="Mapa de Fortaleza, Eusébio e Maracanaú"
          className="mx-auto w-full max-w-lg"
          ref={svgRef}
          role="img"
          viewBox={VIEWBOX}
        >
          {CITIES.map(({ nome, path }) => (
            <path
              className="cidade-path text-emerald-600 dark:text-emerald-400"
              d={path}
              fill="rgba(5,150,105,0.08)"
              key={nome}
              stroke="currentColor"
              strokeLinejoin="round"
              strokeWidth="2.5"
            />
          ))}
          {CITIES.map(({ nome, centro: [x, y], label: [lx, ly] }) => (
            <g key={nome}>
              <g className="cidade-pin">
                <circle
                  cx={x}
                  cy={y}
                  fill="#059669"
                  r="5"
                  stroke="white"
                  strokeWidth="1.5"
                />
              </g>
              <text
                className="cidade-label fill-foreground"
                fontSize="18"
                fontWeight="600"
                x={lx}
                y={ly}
              >
                {nome}
              </text>
            </g>
          ))}
        </svg>

        <ul className="space-y-6">
          {CITIES.map(({ nome }) => (
            <li className="cidade-item flex items-start gap-3" key={nome}>
              <span className="mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full bg-emerald-500" />
              <div>
                <div className="font-semibold">{nome}</div>
                <p className="text-muted-foreground text-sm">
                  Atendimento presencial para compra, venda e locação.
                </p>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
